<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            background: #1a1a2e;
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            color: #eee;
        }
        #game {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }
        #header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            width: 420px;
        }
        #score {
            font-size: 24px;
            font-weight: bold;
        }
        #reset {
            padding: 10px 20px;
            font-size: 16px;
            background: #e94560;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }
        #reset:hover {
            background: #c73650;
        }
        #board {
            display: grid;
            grid-template-columns: repeat(4, 100px);
            grid-template-rows: repeat(4, 100px);
            gap: 10px;
            background: #16213e;
            padding: 10px;
            border-radius: 10px;
        }
        .cell {
            width: 100px;
            height: 100px;
            background: #0f3460;
            border-radius: 5px;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 24px;
            font-weight: bold;
        }
        .tile-2 { background: #eee4da; color: #776e65; }
        .tile-4 { background: #ede0c8; color: #776e65; }
        .tile-8 { background: #f2b179; color: #f9f6f2; }
        .tile-16 { background: #f59563; color: #f9f6f2; }
        .tile-32 { background: #f67c5f; color: #f9f6f2; }
        .tile-64 { background: #f65e3b; color: #f9f6f2; }
        .tile-128 { background: #edcf72; color: #f9f6f2; }
        .tile-256 { background: #edcc61; color: #f9f6f2; }
        .tile-512 { background: #edc850; color: #f9f6f2; }
        .tile-1024 { background: #edc53f; color: #f9f6f2; }
        .tile-2048 { background: #edc22e; color: #f9f6f2; }
    </style>
</head>
<body>
    <div id="game">
        <div id="header">
            <div id="score">Score: 0</div>
            <button id="reset">New Game</button>
        </div>
        <div id="board"></div>
    </div>
    <script>
        let grid = [];
        let score = 0;
        const size = 4;

        const boardEl = document.getElementById('board');
        const scoreEl = document.getElementById('score');
        const resetEl = document.getElementById('reset');

        for (let i = 0; i < size * size; i++) {
            const cell = document.createElement('div');
            cell.className = 'cell';
            boardEl.appendChild(cell);
        }

        function updateDisplay() {
            const cells = boardEl.children;
            for (let r = 0; r < size; r++) {
                for (let c = 0; c < size; c++) {
                    const val = grid[r][c];
                    const idx = r * size + c;
                    cells[idx].className = 'cell';
                    if (val !== 0) {
                        cells[idx].classList.add('tile-' + val);
                        cells[idx].textContent = val;
                    } else {
                        cells[idx].textContent = '';
                    }
                }
            }
            scoreEl.textContent = 'Score: ' + score;
        }

        function getEmptyCells() {
            const empty = [];
            for (let r = 0; r < size; r++) {
                for (let c = 0; c < size; c++) {
                    if (grid[r][c] === 0) {
                        empty.push({r, c});
                    }
                }
            }
            return empty;
        }

        function spawnTile() {
            const empty = getEmptyCells();
            if (empty.length === 0) return;
            const {r, c} = empty[Math.floor(Math.random() * empty.length)];
            grid[r][c] = Math.random() < 0.9 ? 2 : 4;
        }

        function slideRow(row) {
            let filtered = row.filter(x => x !== 0);
            let merged = [];
            let scoreGain = 0;
            let i = 0;
            while (i < filtered.length) {
                if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
                    let val = filtered[i] * 2;
                    merged.push(val);
                    scoreGain += val;
                    i += 2;
                } else {
                    merged.push(filtered[i]);
                    i++;
                }
            }
            while (merged.length < size) {
                merged.push(0);
            }
            return { row: merged, scoreGain };
        }

        function move(direction) {
            let totalScoreGain = 0;
            let moved = false;

            if (direction === 'left') {
                for (let r = 0; r < size; r++) {
                    let result = slideRow(grid[r]);
                    if (result.row.join(',') !== grid[r].join(',')) moved = true;
                    grid[r] = result.row;
                    totalScoreGain += result.scoreGain;
                }
            } else if (direction === 'right') {
                for (let r = 0; r < size; r++) {
                    let reversed = [...grid[r]].reverse();
                    let result = slideRow(reversed);
                    let final = result.row.reverse();
                    if (final.join(',') !== grid[r].join(',')) moved = true;
                    grid[r] = final;
                    totalScoreGain += result.scoreGain;
                }
            } else if (direction === 'up') {
                for (let c = 0; c < size; c++) {
                    let col = [grid[0][c], grid[1][c], grid[2][c], grid[3][c]];
                    let result = slideRow(col);
                    if (result.row.join(',') !== col.join(',')) moved = true;
                    for (let r = 0; r < size; r++) {
                        grid[r][c] = result.row[r];
                    }
                    totalScoreGain += result.scoreGain;
                }
            } else if (direction === 'down') {
                for (let c = 0; c < size; c++) {
                    let col = [grid[0][c], grid[1][c], grid[2][c], grid[3][c]];
                    let reversed = [...col].reverse();
                    let result = slideRow(reversed);
                    let final = result.row.reverse();
                    if (final.join(',') !== col.join(',')) moved = true;
                    for (let r = 0; r < size; r++) {
                        grid[r][c] = final[r];
                    }
                    totalScoreGain += result.scoreGain;
                }
            }

            if (moved) {
                score += totalScoreGain;
                spawnTile();
                updateDisplay();
            }

            return moved;
        }

        function reset() {
            grid = Array(size).fill(null).map(() => Array(size).fill(0));
            score = 0;
            spawnTile();
            spawnTile();
            updateDisplay();
        }

        function getBoard() {
            return grid.map(row => [...row]);
        }

        function setBoard(arr) {
            grid = arr.map(row => [...row]);
            updateDisplay();
        }

        function getScore() {
            return score;
        }

        window.game = {
            size: size,
            reset: reset,
            move: move,
            board: getBoard,
            setBoard: setBoard,
            score: getScore,
        };

        resetEl.addEventListener('click', reset);

        document.addEventListener('keydown', (e) => {
            let dir = null;
            if (e.key === 'ArrowLeft') dir = 'left';
            else if (e.key === 'ArrowRight') dir = 'right';
            else if (e.key === 'ArrowUp') dir = 'up';
            else if (e.key === 'ArrowDown') dir = 'down';

            if (dir) {
                e.preventDefault();
                move(dir);
            }
        });

        reset();
    </script>
</body>
</html>
